values ('LLZDBJYJJ', '03', 'SQL', 'SELECT 0 RVALUE,FINPROD_ID RKEY FROM FIN_PRODUCT_TYPE  WHERE BRANCH=0 AND TYPE_8=''F01'' AND TYPE_6 IN (''B12'',''B01'',''B02'',''B03'') or (TYPE_6=''B05'' AND TYPE_7=''01'')', 'assetCode', 'N', 'admin', '001', sysdate, 'admin', sysdate);

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('LLZDBJYJJ', '04', 'SQL', 'SELECT DISTINCT n.UNIT_CPRICE as RVALUE ,n.FINPROD_ID RKEY
  from TRD_PRODUCT_DEAL_ADD m
  inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.FINPROD_TYPE2 =''F01'' AND n.PS IN (''T01'',''T02'',''T03'') and n.TRADE_STATUS != ''03'' and n.IS_CANCEL = ''N''
  INNER JOIN FIN_PRODUCT_TYPE s ON s.FINPROD_ID=n.FINPROD_ID AND s.BRANCH=0 AND (s.TYPE_6 IN (''B12'',''B01'',''B02'',''B03'') OR (s.TYPE_6=''B05'' AND s.TYPE_7=''01''))
  where  m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}''
  UNION all
  select DISTINCT n.UNIT_CPRICE as RVALUE ,n.FINPROD_ID RKEY
  from WFL_TRD_PRODUCT_DEAL_ADD m
  inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.FINPROD_TYPE2 =''F01'' AND n.PS IN (''T01'',''T02'',''T03'') and n.TRADE_STATUS != ''03'' and n.IS_CANCEL = ''N''
  INNER JOIN FIN_PRODUCT_TYPE s ON s.FINPROD_ID=n.FINPROD_ID AND s.BRANCH=0 AND (s.TYPE_6 IN (''B12'',''B01'',''B02'',''B03'') OR (s.TYPE_6=''B05'' AND s.TYPE_7=''01''))
  where  m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}''', 'assetCode', 'N', 'admin', '001', sysdate, 'admin', sysdate);

